INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Kabel für Video immer auch Audio überträgt?', 2, '[{"text": "Ja", "correct": true, "because": "Es kombiniert beides"}, {"text": "Nein", "correct": false, "because": "Audio ist integriert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature macht eine moderne Schnittstelle für Monitore besonders nützlich?', 3, '[{"text": "Hohe Bandbreite", "correct": true, "because": "Ermöglicht 4K und mehr"}, {"text": "Kleine Stecker", "correct": false, "because": "Nur praktisch, nicht entscheidend"}, {"text": "Bunte Kabel", "correct": false, "because": "Irrelevant für Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften unterstützt ein Kabel für Multimedia?', 5, '[{"text": "Videoübertragung", "correct": true, "because": "Hauptfunktion"}, {"text": "Audioübertragung", "correct": true, "because": "Integrierter Ton"}, {"text": "Netzwerkverbindung", "correct": false, "because": "Nicht dafür gedacht"}, {"text": "Stromversorgung", "correct": false, "because": "Nur begrenzt möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Es überträgt digitale Signale. b) Es ist mit analogen Geräten kompatibel.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nur digital, keine analoge Unterstützung"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich einen Monitor anschließe?', 4, '[{"text": "Auflösungsunterstützung", "correct": false, "because": "Bestimmt Bildqualität"}, {"text": "Kabelversion", "correct": false, "because": "Beeinflusst Funktionen"}, {"text": "Gerätefarbe", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass jede Version 4K unterstützt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Ältere Versionen begrenzt"}, {"text": "Ja", "correct": false, "because": "Erst ab 1.4 möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Version wähle ich für 8K-Video?', 3, '[{"text": "2.1", "correct": true, "because": "Bietet genug Bandbreite"}, {"text": "1.4", "correct": false, "because": "Zu wenig für 8K"}, {"text": "1.0", "correct": false, "because": "Veraltete Version"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine moderne Schnittstelle?', 5, '[{"text": "Hohe Auflösung", "correct": true, "because": "Bis zu 8K möglich"}, {"text": "Einfache Verbindung", "correct": true, "because": "Ein Kabel für alles"}, {"text": "Datenübertragung", "correct": false, "because": "Nicht primär dafür"}, {"text": "Bluetooth", "correct": false, "because": "Kein Feature davon"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass a) es HDCP unterstützt und b) jedes Kabel Ethernet kann. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ethernet nur bei bestimmten Typen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine Verbindung zum Fernseher?', 4, '[{"text": "Kompatible Version", "correct": false, "because": "Sichert Funktionalität"}, {"text": "Geeignete Bandbreite", "correct": false, "because": "Für hohe Auflösung nötig"}, {"text": "USB-Adapter", "correct": true, "because": "Nicht dafür gedacht"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Unterstützt jede Schnittstelle HDR?', 2, '[{"text": "Nein", "correct": true, "because": "Ab Version 2.0 möglich"}, {"text": "Ja", "correct": false, "because": "Ältere Versionen nicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme kann ein altes Kabel verursachen?', 4, '[{"text": "Geringere Auflösung", "correct": true, "because": "Weniger Bandbreite"}, {"text": "Kein Ton", "correct": true, "because": "Fehlende Unterstützung"}, {"text": "Langsamer Internetzugang", "correct": false, "because": "Nicht primäre Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass es mit jedem Gerät funktioniert. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Braucht kompatible Anschlüsse"}, {"text": "Ja", "correct": false, "because": "Nicht universell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Kabel der Version 2.0?', 3, '[{"text": "4K bei 60 Hz", "correct": true, "because": "Bietet genug Bandbreite"}, {"text": "8K-Unterstützung", "correct": false, "because": "Erst ab 2.1"}, {"text": "Analoge Signale", "correct": false, "because": "Nur digital"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Es überträgt bis 48 Gbps in neueren Versionen. b) Es ersetzt USB vollständig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "USB hat andere Zwecke"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt HDCP bei der Nutzung?', 4, '[{"text": "Kopierschutz", "correct": true, "because": "Schützt Inhalte"}, {"text": "Bildverbesserung", "correct": false, "because": "Kein Qualitätsfaktor"}, {"text": "Tonverstärkung", "correct": false, "because": "Nicht dafür zuständig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Adapter für ältere Geräte nötig ist?', 2, '[{"text": "Ja", "correct": true, "because": "Für DVI oder VGA"}, {"text": "Nein", "correct": false, "because": "Kompatibilität oft eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktion macht es für Konferenzräume ideal?', 5, '[{"text": "Ein-Kabel-Lösung", "correct": true, "because": "Video und Audio zusammen"}, {"text": "Hohe Auflösung", "correct": true, "because": "Klarheit bei Präsentationen"}, {"text": "Netzwerkfähigkeit", "correct": false, "because": "Nur optional"}, {"text": "Bluetooth", "correct": false, "because": "Kein Feature"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Brauche ich für jeden Monitor ein anderes Kabel?', 3, '[{"text": "Nein", "correct": true, "because": "Kompatibilität entscheidet"}, {"text": "Ja", "correct": false, "because": "Standardisiert nutzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt am besten zu einem modernen Kabel?', 4, '[{"text": "4K-Streaming", "correct": true, "because": "Hohe Bandbreite nötig"}, {"text": "Textverarbeitung", "correct": false, "because": "Geringe Anforderungen"}, {"text": "Einfache Telefonie", "correct": false, "because": "Kein Video nötig"}]');
